"""The journal file: reading and writing a whole book as text."""
import re
from dataclasses import dataclass, field
from typing import List

from tallybook.accounts import ROOT_TYPES, valid_path
from tallybook.currency import CURRENCIES
from tallybook.dates import DateError, format_date, is_date, parse_date
from tallybook.errors import ParseError
from tallybook.ledger import Ledger
from tallybook.model import Account, Posting, Transaction
from tallybook.money import MoneyError, parse_amount


class JournalError(ParseError):
    def __init__(self, message="", line=None, **extra):
        super().__init__(message, line=line, **extra)


@dataclass
class Journal:
    accounts: List[Account] = field(default_factory=list)
    rates: List[tuple] = field(default_factory=list)
    transactions: List[Transaction] = field(default_factory=list)

    def to_ledger(self):
        ledger = Ledger()
        for a in self.accounts:
            ledger.chart.add(a.path, a.type, a.currency, a.opened, a.note)
            if a.closed is not None:
                ledger.chart.close(a.path, a.closed)
        for src, dst, on, text in self.rates:
            ledger.rates.set(src, dst, text, on)
        for tx in self.transactions:
            ledger.add(tx)
        return ledger


_BLANK = " \t"
_RATE = re.compile(r"[0-9]+(?:\.[0-9]{1,8})?")
_TAG = re.compile(r"#([A-Za-z0-9][A-Za-z0-9_-]*)")


class _Bad(Exception):
    pass


def _tokenize(line):
    """Split a line into [(kind, text)] with kind 'w' (word) or 's' (string); returns (tokens, comment)."""
    tokens = []
    i = 0
    n = len(line)
    comment = None
    while i < n:
        c = line[i]
        if c in _BLANK:
            i += 1
            continue
        if c == ";":
            comment = line[i + 1:]
            break
        if c == '"':
            i += 1
            buf = []
            while True:
                if i >= n:
                    raise _Bad("unterminated quoted string")
                c = line[i]
                if c == "\\":
                    if i + 1 < n and line[i + 1] in '"\\':
                        buf.append(line[i + 1])
                        i += 2
                        continue
                    raise _Bad("bad backslash in quoted string")
                if c == '"':
                    i += 1
                    break
                buf.append(c)
                i += 1
            if i < n and line[i] not in _BLANK and line[i] != ";":
                raise _Bad("unexpected text after quoted string")
            tokens.append(("s", "".join(buf)))
            continue
        j = i
        while j < n and line[j] not in _BLANK and line[j] != ";":
            if line[j] == '"':
                raise _Bad("unexpected quote inside a word")
            j += 1
        tokens.append(("w", line[i:j]))
        i = j
    return tokens, comment


def _date(text):
    try:
        return parse_date(text)
    except DateError as e:
        raise _Bad(e.message) from None


def _currency(text):
    if text not in CURRENCIES:
        raise _Bad("unknown currency %r" % text)
    return text


def _parse_account(tokens):
    rest = tokens[1:]
    if not rest or rest[0][0] != "w":
        raise _Bad("account needs a path")
    path = rest[0][1]
    if not valid_path(path):
        raise _Bad("invalid account path %r" % path)
    i = 1
    cur = opened = closed = None
    note = ""
    if i < len(rest) and rest[i][0] == "w" and rest[i][1] not in ("open", "close"):
        cur = _currency(rest[i][1])
        i += 1
    if i < len(rest) and rest[i] == ("w", "open"):
        if i + 1 >= len(rest) or rest[i + 1][0] != "w":
            raise _Bad("open needs a date")
        opened = _date(rest[i + 1][1])
        i += 2
    if i < len(rest) and rest[i] == ("w", "close"):
        if i + 1 >= len(rest) or rest[i + 1][0] != "w":
            raise _Bad("close needs a date")
        closed = _date(rest[i + 1][1])
        i += 2
    if i < len(rest) and rest[i][0] == "s":
        note = rest[i][1]
        i += 1
    if i != len(rest):
        raise _Bad("unexpected %r in account line" % rest[i][1])
    if opened is not None and closed is not None and closed < opened:
        raise _Bad("account closes before it opens")
    return Account(path, ROOT_TYPES[path.split(":", 1)[0]], cur, opened, closed, note)


def _parse_rate(tokens):
    if len(tokens) != 5 or any(k != "w" for k, _ in tokens):
        raise _Bad("rate line needs: rate DATE FROM TO RATE")
    on = _date(tokens[1][1])
    src = _currency(tokens[2][1])
    dst = _currency(tokens[3][1])
    if src == dst:
        raise _Bad("rate needs two different currencies")
    text = tokens[4][1]
    if _RATE.fullmatch(text) is None or not text.strip("0."):
        raise _Bad("invalid rate %r" % text)
    return (src, dst, on, text)


def _parse_tx_head(tokens):
    on = _date(tokens[0][1]) if tokens[0][0] == "w" else None
    if on is None:
        raise _Bad("a transaction line starts with a date")
    i = 1
    flag = "*"
    if i < len(tokens) and tokens[i][0] == "w" and tokens[i][1] in ("*", "!"):
        flag = tokens[i][1]
        i += 1
    strings = []
    while i < len(tokens) and tokens[i][0] == "s":
        strings.append(tokens[i][1])
        i += 1
    if not strings:
        raise _Bad("transaction needs a quoted payee")
    if len(strings) > 2:
        raise _Bad("transaction takes at most a payee and a narration")
    tags = set()
    while i < len(tokens):
        kind, text = tokens[i]
        m = _TAG.fullmatch(text) if kind == "w" else None
        if m is None:
            raise _Bad("unexpected %r in transaction line" % text)
        tags.add(m.group(1))
        i += 1
    narration = strings[1] if len(strings) == 2 else ""
    return Transaction(on, strings[0], narration, [], tuple(sorted(tags)), flag, None)


def _parse_posting(tokens, comment):
    if not tokens or any(k != "w" for k, _ in tokens):
        raise _Bad("a posting is ACCOUNT or ACCOUNT AMOUNT CUR")
    account = tokens[0][1]
    if not valid_path(account):
        raise _Bad("invalid account path %r" % account)
