"""The journal file: reading and writing a whole book as text."""
import re
from dataclasses import dataclass, field
from typing import List

from tallybook.accounts import ROOT_TYPES, valid_path
from tallybook.currency import CURRENCIES
from tallybook.dates import DateError, format_date, is_date, parse_date
from tallybook.errors import ParseError
from tallybook.ledger import Ledger
from tallybook.model import Account, Posting, Transaction
from tallybook.money import MoneyError, parse_amount


class JournalError(ParseError):
    def __init__(self, message="", line=None, **extra):
        super().__init__(message, line=line, **extra)


@dataclass
class Journal:
    accounts: List[Account] = field(default_factory=list)
    rates: List[tuple] = field(default_factory=list)
    transactions: List[Transaction] = field(default_factory=list)

    def to_ledger(self):
        ledger = Ledger()
        for a in self.accounts:
            ledger.chart.add(a.path, a.type, a.currency, a.opened, a.note)
            if a.closed is not None:
                ledger.chart.close(a.path, a.closed)
        for src, dst, on, text in self.rates:
            ledger.rates.set(src, dst, text, on)
        for tx in self.transactions:
            ledger.add(tx)
        return ledger


_BLANK = " \t"
_RATE = re.compile(r"[0-9]+(?:\.[0-9]{1,8})?")
_TAG = re.compile(r"#([A-Za-z0-9][A-Za-z0-9_-]*)")


class _Bad(Exception):
    pass


def _tokenize(line):
    """Split a line into [(kind, text)] with kind 'w' (word) or 's' (string); returns (tokens, comment)."""
    tokens = []
    i = 0
    n = len(line)
    comment = None
    while i < n:
        c = line[i]
        if c in _BLANK:
            i += 1
            continue
        if c == ";":
            comment = line[i + 1:]
            break
        if c == '"':
            i += 1
            buf = []
            while True:
                if i >= n:
                    raise _Bad("unterminated quoted string")
                c = line[i]
                if c == "\\":
                    if i + 1 < n and line[i + 1] in '"\\':
                        buf.append(line[i + 1])
                        i += 2
                        continue
                    raise _Bad("bad backslash in quoted string")
                if c == '"':
                    i += 1
                    break
                buf.append(c)
                i += 1
            if i < n and line[i] not in _BLANK and line[i] != ";":
                raise _Bad("unexpected text after quoted string")
            tokens.append(("s", "".join(buf)))
            continue
        j = i
        while j < n and line[j] not in _BLANK and line[j] != ";":
            if line[j] == '"':
                raise _Bad("unexpected quote inside a word")
            j += 1
        tokens.append(("w", line[i:j]))
        i = j
    return tokens, comment


def _date(text):
    try:
        return parse_date(text)
    except DateError as e:
        raise _Bad(e.message) from None


def _currency(text):
    if text not in CURRENCIES:
        raise _Bad("unknown currency %r" % text)
    return text


def _parse_account(tokens):
    rest = tokens[1:]
    if not rest or rest[0][0] != "w":
        raise _Bad("account needs a path")
    path = rest[0][1]
    if not valid_path(path):
        raise _Bad("invalid account path %r" % path)
    i = 1
    cur = opened = closed = None
    note = ""
    if i < len(rest) and rest[i][0] == "w" and rest[i][1] not in ("open", "close"):
        cur = _currency(rest[i][1])
        i += 1
    if i < len(rest) and rest[i] == ("w", "open"):
        if i + 1 >= len(rest) or rest[i + 1][0] != "w":
            raise _Bad("open needs a date")
        opened = _date(rest[i + 1][1])
        i += 2
    if i < len(rest) and rest[i] == ("w", "close"):
        if i + 1 >= len(rest) or rest[i + 1][0] != "w":
            raise _Bad("close needs a date")
        closed = _date(rest[i + 1][1])
        i += 2
    if i < len(rest) and rest[i][0] == "s":
        note = rest[i][1]
        i += 1
    if i != len(rest):
        raise _Bad("unexpected %r in account line" % rest[i][1])
    if opened is not None and closed is not None and closed < opened:
        raise _Bad("account closes before it opens")
    return Account(path, ROOT_TYPES[path.split(":", 1)[0]], cur, opened, closed, note)


def _parse_rate(tokens):
    if len(tokens) != 5 or any(k != "w" for k, _ in tokens):
        raise _Bad("rate line needs: rate DATE FROM TO RATE")
    on = _date(tokens[1][1])
    src = _currency(tokens[2][1])
    dst = _currency(tokens[3][1])
    if src == dst:
        raise _Bad("rate needs two different currencies")
    text = tokens[4][1]
    if _RATE.fullmatch(text) is None or not text.strip("0."):
        raise _Bad("invalid rate %r" % text)
    return (src, dst, on, text)


def _parse_tx_head(tokens):
    on = _date(tokens[0][1]) if tokens[0][0] == "w" else None
    if on is None:
        raise _Bad("a transaction line starts with a date")
    i = 1
    flag = "*"
    if i < len(tokens) and tokens[i][0] == "w" and tokens[i][1] in ("*", "!"):
        flag = tokens[i][1]
        i += 1
    strings = []
    while i < len(tokens) and tokens[i][0] == "s":
        strings.append(tokens[i][1])
        i += 1
    if not strings:
        raise _Bad("transaction needs a quoted payee")
    if len(strings) > 2:
        raise _Bad("transaction takes at most a payee and a narration")
    tags = set()
    while i < len(tokens):
        kind, text = tokens[i]
        m = _TAG.fullmatch(text) if kind == "w" else None
        if m is None:
            raise _Bad("unexpected %r in transaction line" % text)
        tags.add(m.group(1))
        i += 1
    narration = strings[1] if len(strings) == 2 else ""
    return Transaction(on, strings[0], narration, [], tuple(sorted(tags)), flag, None)


def _parse_posting(tokens, comment):
    if not tokens or any(k != "w" for k, _ in tokens):
        raise _Bad("a posting is ACCOUNT or ACCOUNT AMOUNT CUR")
    account = tokens[0][1]
    if not valid_path(account):
        raise _Bad("invalid account path %r" % account)
    note = comment.strip(_BLANK) if comment is not None else ""
    if len(tokens) == 1:
        return Posting(account, None, note)
    if len(tokens) != 3:
        raise _Bad("a posting is ACCOUNT or ACCOUNT AMOUNT CUR")
    cur = _currency(tokens[2][1])
    try:
        minor = parse_amount(tokens[1][1], cur)
    except MoneyError as e:
        raise _Bad(e.message) from None
    from tallybook.money import Money

    return Posting(account, Money(minor, cur), note)


def parse_journal(text):
    if not isinstance(text, str):
        raise JournalError("line 1: journal must be text", line=1)
    if text.startswith("\ufeff"):
        text = text[1:]
    pieces = text.split("\n")
    lines = [p[:-1] if p.endswith("\r") and k < len(pieces) - 1 else p for k, p in enumerate(pieces)]
    journal = Journal()
    seen = set()
    current = None
    for number, line in enumerate(lines, 1):
        try:
            if line.strip(_BLANK) == "":
                current = None
                continue
            first = line.lstrip(_BLANK)
            if first[0] in ";#":
                continue
            tokens, comment = _tokenize(line)
            if line[0] in _BLANK:
                if current is None:
                    raise _Bad("indented line outside a transaction")
                current.postings.append(_parse_posting(tokens, comment))
                continue
            current = None
            head = tokens[0]
            if head == ("w", "account"):
                acct = _parse_account(tokens)
                if acct.path in seen:
                    raise _Bad("account %s declared twice" % acct.path)
                seen.add(acct.path)
                journal.accounts.append(acct)
            elif head == ("w", "rate"):
                journal.rates.append(_parse_rate(tokens))
            else:
                if head[0] == "w" and not head[1][:1].isdigit():
                    raise _Bad("unknown directive %r" % head[1])
                current = _parse_tx_head(tokens)
                journal.transactions.append(current)
        except _Bad as e:
            raise JournalError("line %d: %s" % (number, e), line=number) from None
    return journal


def _quote(text):
    return '"' + text.replace("\\", "\\\\").replace('"', '\\"') + '"'


def format_transaction(tx):
    head = "%s %s %s" % (format_date(tx.date), tx.flag, _quote(tx.payee))
    if tx.narration:
        head += " " + _quote(tx.narration)
    for tag in sorted(set(tx.tags)):
        head += " #" + tag
    out = [head]
    amounts = [p.amount.amount_str() for p in tx.postings if p.amount is not None]
    name_w = max([len(p.account) for p in tx.postings if p.amount is not None] or [0])
    amount_w = max([len(a) for a in amounts] or [0])
    for p in tx.postings:
        if p.amount is None:
            row = "  " + p.account
        else:
            row = "  %s  %s %s" % (p.account.ljust(name_w), p.amount.amount_str().rjust(amount_w), p.amount.currency)
        if p.note:
            row += "  ; " + p.note
        out.append(row)
    return "\n".join(out) + "\n"


def format_journal(journal):
    groups = []
    if journal.accounts:
        lines = []
        for a in journal.accounts:
            row = "account " + a.path
            if a.currency:
                row += " " + a.currency
            if a.opened is not None:
                row += " open " + format_date(a.opened)
            if a.closed is not None:
                row += " close " + format_date(a.closed)
            if a.note:
                row += " " + _quote(a.note)
            lines.append(row)
        groups.append("\n".join(lines) + "\n")
    if journal.rates:
        groups.append(
            "\n".join("rate %s %s %s %s" % (format_date(on), src, dst, text) for src, dst, on, text in journal.rates)
            + "\n"
        )
    for tx in journal.transactions:
        groups.append(format_transaction(tx))
    return "\n".join(groups)

"""The query language: find transactions without writing Python."""
import re
from fractions import Fraction
from functools import lru_cache

from tallybook.currency import CURRENCIES
from tallybook.dates import DateError, Period, parse_date
from tallybook.errors import ParseError


class QueryError(ParseError):
    def __init__(self, message="", position=None, **extra):
        super().__init__(message, position=position, **extra)


def _fail(what, position):
    raise QueryError("%s at position %d" % (what, position), position=position)


_SPACE = " \t\r\n\f\v"
_NAMES = ("payee", "narration", "tag", "date", "flag", "id", "account")
_OPS = ("<=", ">=", "!=", "<", ">", "=")
_AMOUNT = re.compile(r"([+-]?[0-9]+(?:\.[0-9]+)?)([A-Z]{3})?")
_PART = re.compile(r"[A-Za-z0-9_-]+")
_ID = re.compile(r"[0-9]+")

_CMP = {
    "<": lambda a, b: a < b,
    "<=": lambda a, b: a <= b,
    ">": lambda a, b: a > b,
    ">=": lambda a, b: a >= b,
    "=": lambda a, b: a == b,
    "!=": lambda a, b: a != b,
}


def _account_matches(parts, path):
    segs = path.split(":")

    @lru_cache(maxsize=None)
    def go(i, j):
        if i == len(parts):
            return True
        head = parts[i]
        if head == "**":
            return any(go(i + 1, k) for k in range(j, len(segs) + 1))
        if j >= len(segs):
            return False
        if head == "*" or head == segs[j]:
            return go(i + 1, j + 1)
        return False

    return go(0, 0)


# ---- expression nodes: (kind, ...) evaluated per posting -------------------


def _eval(node, tx, posting):
    kind = node[0]
    if kind == "and":
        return _eval(node[1], tx, posting) and _eval(node[2], tx, posting)
    if kind == "or":
        return _eval(node[1], tx, posting) or _eval(node[2], tx, posting)
    if kind == "not":
        return not _eval(node[1], tx, posting)
    if kind == "text":
        needle = node[1]
        return needle in tx.payee.lower() or needle in tx.narration.lower()
    if kind == "payee":
        return node[1] in tx.payee.lower()
    if kind == "narration":
        return node[1] in tx.narration.lower()
    if kind == "tag":
        return node[1] in tx.tags
    if kind == "flag":
        return tx.flag == node[1]
    if kind == "id":
        return tx.id is not None and tx.id == node[1]
    if kind == "period":
        return node[1].contains(tx.date)
    if kind == "datecmp":
        return _CMP[node[1]](tx.date, node[2])
    if kind == "account":
        return _account_matches(node[1], posting.account)
    if kind == "amount":
        amount = posting.amount
        if amount is None:
            return False
        if node[3] is not None and amount.currency != node[3]:
            return False
        return _CMP[node[1]](Fraction(amount.minor, 10 ** amount.exponent), node[2])
    raise AssertionError(kind)


class Query:
    def __init__(self, text, node):
        self.text = text
        self._node = node
        self.is_empty = node is None

    def __repr__(self):
        return "Query(%r)" % (self.text,)

    def matching_postings(self, tx):
        if self._node is None:
            return list(tx.postings)
        return [p for p in tx.postings if _eval(self._node, tx, p)]

    def matches(self, tx):
        if self._node is None:
            return True
        return any(_eval(self._node, tx, p) for p in tx.postings)


class _Parser:
    def __init__(self, text, chart):
        self.text = text
        self.chart = chart
        self.n = len(text)
        self.i = 0
        self.peeked = None

    # -- lexer -----------------------------------------------------------
    def _skip(self):
        while self.i < self.n and self.text[self.i] in _SPACE:
            self.i += 1

    def _run(self):
        start = self.i
        while self.i < self.n and self.text[self.i] not in _SPACE and self.text[self.i] not in "()":
            self.i += 1
        return self.text[start:self.i]

    def _quoted(self):
        """Read a quoted string starting at self.i; return its text."""
        open_pos = self.i
        self.i += 1
        buf = []
        while True:
            if self.i >= self.n:
                _fail("unterminated quote", open_pos + 1)
            c = self.text[self.i]
            if c == "\\" and self.i + 1 < self.n and self.text[self.i + 1] in '"\\':
                buf.append(self.text[self.i + 1])
                self.i += 2
                continue
            if c == '"':
                self.i += 1
                break
            buf.append(c)
            self.i += 1
        if self.i < self.n and self.text[self.i] not in _SPACE and self.text[self.i] not in "()":
            _fail("unexpected text after closing quote", self.i + 1)
        return "".join(buf)

    def _token(self):
        """Next token: ('(', pos) (')', pos) ('and'|'or'|'not', pos) ('term', pos, node) or ('end', pos)."""
        self._skip()
        if self.i >= self.n:
            return ("end", self.n + 1)
        pos = self.i
        c = self.text[pos]
        if c == "(" or c == ")":
            self.i += 1
            return (c, pos + 1)
        if c == '"':
            value = self._quoted()
            if value == "":
                _fail("empty quotes", pos + 1)
            return ("term", pos + 1, ("text", value.lower()))
        j = pos
        while j < self.n and self.text[j] not in _SPACE and self.text[j] not in '()":<>=!':
            j += 1
        name = self.text[pos:j].lower()
        if j < self.n and self.text[j] == ":":
            return self._named(pos, j, name)
        if name in ("amount", "date") and j == self.i + len(name) - 0 and self._comparison_ahead(j):
            return self._comparison(pos, j, name)
        word = self._run()
        if word.lower() in ("and", "or", "not"):
            return (word.lower(), pos + 1)
        return ("term", pos + 1, ("text", word.lower()))

    def _comparison_ahead(self, j):
        while j < self.n and self.text[j] in _SPACE:
            j += 1
        return any(self.text.startswith(op, j) for op in _OPS)

    def _named(self, pos, colon, name):
        term_pos = pos + 1
        if name not in _NAMES:
            _fail("unknown term %r" % self.text[pos:colon], term_pos)
        self.i = colon + 1
        if self.i < self.n and self.text[self.i] == '"':
            value = self._quoted()
        else:
            value = self._run()
        if value == "":
            _fail("missing value for %r" % name, term_pos)
        node = self._named_node(name, value, term_pos)
        return ("term", term_pos, node)

    def _named_node(self, name, value, term_pos):
        if name in ("payee", "narration"):
            return (name, value.lower())
        if name == "tag":
            return ("tag", value.lower())
        if name == "flag":
            if value not in ("*", "!"):
                _fail("invalid flag %r" % value, term_pos)
            return ("flag", value)
        if name == "id":
            if _ID.fullmatch(value) is None:
                _fail("invalid id %r" % value, term_pos)
            return ("id", int(value))
        if name == "date":
            try:
                return ("period", Period.parse(value))
            except DateError:
                _fail("invalid date period %r" % value, term_pos)
        parts = tuple(value.split(":"))
        if any(p not in ("*", "**") and _PART.fullmatch(p) is None for p in parts):
            _fail("invalid account pattern %r" % value, term_pos)
        if self.chart is not None:
            if not any(_account_matches(parts, a.path) for a in self.chart.accounts()):
                _fail("no account matches %r" % value, term_pos)
        return ("account", parts)

    def _comparison(self, pos, j, name):
        term_pos = pos + 1
        k = j
        while k < self.n and self.text[k] in _SPACE:
            k += 1
        op = next(o for o in _OPS if self.text.startswith(o, k))
        self.i = k + len(op)
        self._skip()
        value = self._run()
        if value == "":
            _fail("missing value for %r" % name, term_pos)
        if name == "date":
            try:
                return ("term", term_pos, ("datecmp", op, parse_date(value)))
            except DateError:
                _fail("invalid date %r" % value, term_pos)
        m = _AMOUNT.fullmatch(value)
        if m is None:
            _fail("invalid amount %r" % value, term_pos)
        return ("term", term_pos, ("amount", op, Fraction(m.group(1)), m.group(2)))

    # -- grammar -----------------------------------------------------------
    def _peek(self):
        if self.peeked is None:
            self.peeked = self._token()
        return self.peeked

    def _next(self):
        tok = self._peek()
        self.peeked = None
        return tok

    def parse(self):
        if self._peek()[0] == "end":
            return None
        node = self._or()
        tok = self._peek()
        if tok[0] == ")":
            _fail("unmatched ')'", tok[1])
        return node

    def _or(self):
        node = self._and()
        while self._peek()[0] == "or":
            self._next()
            node = ("or", node, self._and())
        return node

    def _and(self):
        node = self._not()
        while True:
            kind = self._peek()[0]
            if kind == "and":
                self._next()
            elif kind not in ("term", "(", "not"):
                return node
            node = ("and", node, self._not())

    def _not(self):
        if self._peek()[0] == "not":
            self._next()
            return ("not", self._not())
        return self._atom()

    def _atom(self):
        tok = self._next()
        kind = tok[0]
        if kind == "term":
            return tok[2]
        if kind == "(":
            node = self._or()
            close = self._peek()
            if close[0] != ")":
                if close[0] == "end":
                    _fail("unclosed '('", tok[1])
                _fail("expected ')'", close[1])
            self._next()
            return node
        _fail("expected a term", tok[1])


def parse_query(text, chart=None):
    if not isinstance(text, str):
        raise QueryError("query must be text at position 1", position=1)
    if text.strip(_SPACE) == "":
        return Query(text, None)
    return Query(text, _Parser(text, chart).parse())


def select(transactions, query):
    if isinstance(query, str):
        query = parse_query(query)
    return [tx for tx in transactions if query.matches(tx)]

