"""Rules: sort transactions into accounts, tags and narrations."""
import re
from dataclasses import dataclass, replace
from fractions import Fraction
from typing import Optional, Tuple

from tallybook.accounts import valid_path
from tallybook.dates import DateError, is_date, parse_date
from tallybook.errors import ParseError
from tallybook.model import Posting

_BLANK = " \t"
_OPS = ("<=", ">=", "!=", "<", ">", "=")
_AMOUNT = re.compile(r"([+-]?[0-9]+(?:\.[0-9]+)?)([A-Z]{3})?")
_TAG = re.compile(r"[A-Za-z0-9_-]+")

_CMP = {
    "<": lambda a, b: a < b,
    "<=": lambda a, b: a <= b,
    ">": lambda a, b: a > b,
    ">=": lambda a, b: a >= b,
    "=": lambda a, b: a == b,
    "!=": lambda a, b: a != b,
}


class RulesError(ParseError):
    def __init__(self, message="", line=None, **extra):
        super().__init__(message, line=line, **extra)


class _Bad(Exception):
    pass


@dataclass(frozen=True)
class Rule:
    line: int
    conditions: tuple = ()
    account: Optional[str] = None
    tags: Tuple[str, ...] = ()
    narration: Optional[str] = None
    payee: Optional[str] = None
    flag: Optional[str] = None

    def matches(self, fields):
        return all(cond(fields) for cond in self.conditions)


def _text_cond(field, op, text, regex):
    if op == "=":
        want = text.lower()
        return lambda f: _text(f, field).lower() == want
    if op == "!=":
        want = text.lower()
        return lambda f: _text(f, field).lower() != want
    if op == "~":
        return lambda f: regex.search(_text(f, field)) is not None
    return lambda f: regex.search(_text(f, field)) is None


def _text(fields, field):
    value = fields.get(field)
    return value if isinstance(value, str) else ""


def _amount_cond(op, number, code):
    compare = _CMP[op]

    def check(fields):
        amount = fields.get("amount")
        if amount is None:
            return False
        if code is not None and amount.currency != code:
            return False
        return compare(Fraction(amount.minor, 10 ** amount.exponent), number)

    return check


def _date_cond(op, day):
    compare = _CMP[op]

    def check(fields):
        value = fields.get("date")
        if not is_date(value):
            return False
        return compare(value, day)

    return check


class _Line:
    def __init__(self, text):
        self.s = text
        self.i = 0

    def skip(self):
        while self.i < len(self.s) and self.s[self.i] in _BLANK:
            self.i += 1

    def at_end(self):
        self.skip()
        return self.i >= len(self.s)

    def word(self, stops=""):
        self.skip()
        start = self.i
        while self.i < len(self.s) and self.s[self.i] not in _BLANK and self.s[self.i] not in stops:
            self.i += 1
        return self.s[start:self.i]

    def op(self, allowed):
        self.skip()
        for candidate in allowed:
            if self.s.startswith(candidate, self.i):
                self.i += len(candidate)
                return candidate
        return None

    def string(self):
        self.skip()
        if self.i >= len(self.s) or self.s[self.i] != '"':
            raise _Bad("expected a quoted text")
        self.i += 1
        buf = []
        while True:
            if self.i >= len(self.s):
                raise _Bad("quoted text is never closed")
            c = self.s[self.i]
            if c == "\\":
                if self.i + 1 >= len(self.s):
                    raise _Bad("quoted text is never closed")
                nxt = self.s[self.i + 1]
                buf.append(nxt if nxt == '"' else c + nxt)
                self.i += 2
                continue
            self.i += 1
            if c == '"':
                break
            buf.append(c)
        if self.i < len(self.s) and self.s[self.i] not in _BLANK:
            raise _Bad("unexpected text after quoted text")
        return "".join(buf)


def _parse_condition(cur):
    field = cur.word('<>=!~"')
    if field in ("payee", "narration"):
        op = cur.op(("!=", "!~", "=", "~"))
        if op is None:
            raise _Bad("%s takes = != ~ or !~" % field)
        text = cur.string()
        regex = None
        if op in ("~", "!~"):
            try:
                regex = re.compile(text, re.IGNORECASE)
            except re.error as e:
                raise _Bad("bad regular expression %r: %s" % (text, e)) from None
        return _text_cond(field, op, text, regex)
    if field in ("amount", "date"):
        op = cur.op(_OPS)
        if op is None:
            raise _Bad("%s takes < <= > >= = or !=" % field)
        value = cur.word()
        if value == "":
            raise _Bad("%s needs a value" % field)
        if field == "date":
            try:
                return _date_cond(op, parse_date(value))
            except DateError:
                raise _Bad("invalid date %r" % value) from None
        m = _AMOUNT.fullmatch(value)
        if m is None:
            raise _Bad("invalid amount %r" % value)
        return _amount_cond(op, Fraction(m.group(1)), m.group(2))
    if field == "":
        raise _Bad("missing condition")
    raise _Bad("unknown field %r" % field)


def _parse_rule(text, number):
    cur = _Line(text)
    if cur.word() != "when":
        raise _Bad("a rule starts with 'when'")
    conditions = []
    cur.skip()
    save = cur.i
    if cur.word() == "any":
        if cur.word() != "then":
            raise _Bad("'any' cannot be combined with other conditions")
    else:
        cur.i = save
        while True:
            conditions.append(_parse_condition(cur))
            joiner = cur.word()
            if joiner == "then":
                break
            if joiner != "and":
                raise _Bad("expected 'and' or 'then'" if joiner else "missing 'then'")
    found = {}
    tags = []
    while not cur.at_end():
        name = cur.word('"')
        if name not in ("account", "tag", "narration", "payee", "flag"):
            raise _Bad("unknown action %r" % name)
        if name in ("narration", "payee"):
            if cur.at_end():
                raise _Bad("%s needs a value" % name)
