        raise _Bad("missing condition")
    raise _Bad("unknown field %r" % field)


def _parse_rule(text, number):
    cur = _Line(text)
    if cur.word() != "when":
        raise _Bad("a rule starts with 'when'")
    conditions = []
    cur.skip()
    save = cur.i
    if cur.word() == "any":
        if cur.word() != "then":
            raise _Bad("'any' cannot be combined with other conditions")
    else:
        cur.i = save
        while True:
            conditions.append(_parse_condition(cur))
            joiner = cur.word()
            if joiner == "then":
                break
            if joiner != "and":
                raise _Bad("expected 'and' or 'then'" if joiner else "missing 'then'")
    found = {}
    tags = []
    while not cur.at_end():
        name = cur.word('"')
        if name not in ("account", "tag", "narration", "payee", "flag"):
            raise _Bad("unknown action %r" % name)
        if name in ("narration", "payee"):
            if cur.at_end():
                raise _Bad("%s needs a value" % name)
            value = cur.string()
            if name == "payee" and value.strip() == "":
                raise _Bad("payee must not be empty")
        else:
            value = cur.word()
            if value == "":
                raise _Bad("%s needs a value" % name)
            if name == "account" and not valid_path(value):
                raise _Bad("invalid account path %r" % value)
            if name == "flag" and value not in ("*", "!"):
                raise _Bad("flag must be * or !")
            if name == "tag" and _TAG.fullmatch(value) is None:
                raise _Bad("invalid tag %r" % value)
        if name == "tag":
            if value.lower() not in tags:
                tags.append(value.lower())
            continue
        if name in found:
            raise _Bad("%s given twice" % name)
        found[name] = value
    if not found and not tags:
        raise _Bad("nothing after 'then'")
    return Rule(number, tuple(conditions), found.get("account"), tuple(tags), found.get("narration"),
                found.get("payee"), found.get("flag"))


class RuleSet:
    def __init__(self, rules=()):
        self._rules = list(rules)

    def __len__(self):
        return len(self._rules)

    def __iter__(self):
        return iter(self._rules)

    def match(self, fields):
        for rule in self._rules:
            if rule.matches(fields):
                return rule
        return None

    def apply(self, fields):
        rule = self.match(fields)
        if rule is None:
            return None
        out = {}
        if rule.account is not None:
            out["account"] = rule.account
        if rule.tags:
            out["tags"] = list(rule.tags)
        if rule.narration is not None:
            out["narration"] = rule.narration
        if rule.payee is not None:
            out["payee"] = rule.payee
        if rule.flag is not None:
            out["flag"] = rule.flag
        return out

    def categorize(self, tx):
        first = tx.postings[0].amount if tx.postings else None
        rule = self.match({"payee": tx.payee, "narration": tx.narration, "amount": first, "date": tx.date})
        if rule is None:
            return tx
        changes = {"tags": tuple(sorted(set(tx.tags) | set(rule.tags)))}
        if rule.payee is not None:
            changes["payee"] = rule.payee
        if rule.narration is not None:
            changes["narration"] = rule.narration
        if rule.flag is not None:
            changes["flag"] = rule.flag
        postings = list(tx.postings)
        if rule.account is not None and len(postings) == 2:
            postings[1] = replace(postings[1], account=rule.account)
        changes["postings"] = postings
        return replace(tx, **changes)


def parse_rules(text):
    if not isinstance(text, str):
        raise RulesError("line 1: rules must be text", line=1)
    if text.startswith("\ufeff"):
        text = text[1:]
    rules = []
    for number, raw in enumerate(text.split("\n"), 1):
        line = raw[:-1] if raw.endswith("\r") else raw
        stripped = line.strip(_BLANK)
        if stripped == "" or stripped.startswith("#"):
            continue
        try:
            rules.append(_parse_rule(stripped, number))
        except _Bad as e:
            raise RulesError("line %d: %s" % (number, e), line=number) from None
    return RuleSet(rules)

"""Importing a bank's CSV statements described by a profile."""
import re
from collections import Counter
from dataclasses import dataclass, field
from datetime import date
from typing import List, Optional, Tuple

from tallybook.currency import CURRENCIES, currency as _currency
from tallybook.errors import ParseError
from tallybook.model import Posting, Transaction
from tallybook.money import Money
from tallybook.rules import RuleSet, parse_rules, valid_rule_path

_TAG = re.compile(r"[A-Za-z0-9_-]+")
_COLUMN_NUMBER = re.compile(r"#([0-9]+)")
_EOL = re.compile(r"\r\n|\n|\r")

_MONTHS = ("january", "february", "march", "april", "may", "june", "july", "august", "september", "october",
           "november", "december")
_MONTH_ABBR = tuple(m[:3] for m in _MONTHS)

_DELIMITERS = {"comma": ",", "tab": "\t", "semicolon": ";", "pipe": "|", "space": " "}
_THOUSANDS = {"none": "", "comma": ",", "dot": ".", "space": " ", "apostrophe": "'"}


class CsvImportError(ParseError):
    def __init__(self, message="", line=None, **extra):
        super().__init__(message, line=line, **extra)


class _Bad(Exception):
    pass


@dataclass
class ImportProfile:
    date_column: str = ""
    payee_column: str = ""
    currency: str = ""
    account: str = ""
    narration_column: Optional[str] = None
    amount_column: Optional[str] = None
    debit_column: Optional[str] = None
    credit_column: Optional[str] = None
    default_account: Optional[str] = None
    date_format: str = "%Y-%m-%d"
    delimiter: str = ","
    skip_rows: int = 0
    has_header: bool = True
    negate: bool = False
    decimal_separator: str = "."
    thousands_separator: str = ""
    flag: str = "*"
    tags: Tuple[str, ...] = ()


@dataclass
class ImportResult:
    transactions: List[Transaction] = field(default_factory=list)
    duplicates: List[Transaction] = field(default_factory=list)
    errors: List[tuple] = field(default_factory=list)


# ---- profile --------------------------------------------------------------


def _bool(value):
    low = value.lower()
    if low in ("yes", "true"):
        return True
    if low in ("no", "false"):
        return False
    raise _Bad("expected yes/no or true/false, got %r" % value)


def _column(value):
    if value == "":
        raise _Bad("column must not be empty")
    if value.startswith("#"):
        m = _COLUMN_NUMBER.fullmatch(value)
        if m is None or int(m.group(1)) < 1:
            raise _Bad("bad column number %r" % value)
    return value


def _account(value):
    if not valid_rule_path(value):
        raise _Bad("invalid account path %r" % value)
    return value


def _currency_code(value):
    if value not in CURRENCIES:
        raise _Bad("unknown currency %r" % value)
    return value


def _delimiter(value):
    if value in _DELIMITERS:
        return _DELIMITERS[value]
    if len(value) == 1 and value not in '"\r\n':
        return value
    raise _Bad("bad delimiter %r" % value)


def _skip_rows(value):
    if re.fullmatch(r"[0-9]+", value) is None:
        raise _Bad("skip_rows must be a whole number, got %r" % value)
    return int(value)


def _decimal(value):
    if value not in (".", ","):
        raise _Bad("decimal_separator must be . or ,")
    return value


def _thousands(value):
    if value in _THOUSANDS:
        return _THOUSANDS[value]
    if value in (",", ".", "'", " "):
        return value
    raise _Bad("bad thousands_separator %r" % value)


def _flag(value):
    if value not in ("*", "!"):
        raise _Bad("flag must be * or !")
    return value


def _tags(value):
    names = [t.strip() for t in value.split(",")]
    if any(_TAG.fullmatch(t) is None for t in names):
        raise _Bad("bad tags %r" % value)
    return tuple(sorted(set(t.lower() for t in names)))


_DIRECTIVES = {
    "Y": "[0-9]{4}",
    "y": "[0-9]{2}",
    "m": "[0-9]{1,2}",
    "d": "[0-9]{1,2}",
    "b": "(?i:%s)" % "|".join(_MONTH_ABBR),
    "B": "(?i:%s)" % "|".join(_MONTHS),
}


def _compile_format(fmt):
    parts = []
    seen = set()
    i = 0
    while i < len(fmt):
        c = fmt[i]
        if c != "%":
            parts.append(re.escape(c))
            i += 1
            continue
        if i + 1 >= len(fmt):
            raise _Bad("date_format ends with a lone %")
        d = fmt[i + 1]
        i += 2
        if d == "%":
            parts.append("%")
            continue
        if d not in _DIRECTIVES:
            raise _Bad("unsupported date_format directive %%%s" % d)
        slot = {"Y": "year", "y": "year", "m": "month", "b": "month", "B": "month", "d": "day"}[d]
        if slot in seen:
            raise _Bad("date_format has more than one %s" % slot)
        seen.add(slot)
        parts.append("(?P<%s_%s>%s)" % (slot, d, _DIRECTIVES[d]))
    if seen != {"year", "month", "day"}:
        raise _Bad("date_format needs a year, a month and a day")
    return "".join(parts)


def _date_format(value):
    _compile_format(value)
    return value


_SETTINGS = {
    "date_column": ("date_column", _column),
    "payee_column": ("payee_column", _column),
    "narration_column": ("narration_column", _column),
    "amount_column": ("amount_column", _column),
    "debit_column": ("debit_column", _column),
    "credit_column": ("credit_column", _column),
    "currency": ("currency", _currency_code),
    "account": ("account", _account),
    "default_account": ("default_account", _account),
    "date_format": ("date_format", _date_format),
    "delimiter": ("delimiter", _delimiter),
    "skip_rows": ("skip_rows", _skip_rows),
    "has_header": ("has_header", _bool),
    "negate": ("negate", _bool),
    "decimal_separator": ("decimal_separator", _decimal),
    "thousands_separator": ("thousands_separator", _thousands),
    "flag": ("flag", _flag),
    "tags": ("tags", _tags),
}
_COLUMNS = ("date_column", "payee_column", "narration_column", "amount_column", "debit_column", "credit_column")


def parse_profile(text):
    if not isinstance(text, str):
        raise CsvImportError("profile must be text")
    if text.startswith("﻿"):
        text = text[1:]
    values = {}
    where = {}
    errors = []
    for number, raw in enumerate(text.split("\n"), 1):
        line = raw[:-1] if raw.endswith("\r") else raw
        stripped = line.strip()
        if stripped == "" or stripped.startswith("#"):
            continue
        try:
            if "=" not in stripped:
                raise _Bad("expected 'setting = value'")
            name, value = stripped.split("=", 1)
            name = name.strip()
            value = value.strip()
            if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
                value = value[1:-1]
            if name not in _SETTINGS:
                raise _Bad("unknown setting %r" % name)
            if name in where:
                raise _Bad("setting %r given twice (first on line %d)" % (name, where[name]))
            where[name] = number
            values[name] = _SETTINGS[name][1](value)
        except _Bad as e:
            errors.append((number, str(e)))
    if values.get("has_header", True) is False:
        for name in _COLUMNS:
            if name in values and not values[name].startswith("#"):
                errors.append((where[name], "column name %r needs has_header = yes; use #N" % values[name]))
    if errors:
        number, message = min(errors, key=lambda e: e[0])
        raise CsvImportError("line %d: %s" % (number, message), line=number)

    def whole(message):
        raise CsvImportError(message, line=None)

    for name in ("date_column", "payee_column", "currency", "account"):
        if name not in values:
            whole("missing required setting %s" % name)
    has_amount = "amount_column" in values
    has_debit = "debit_column" in values
    has_credit = "credit_column" in values
    if has_amount and (has_debit or has_credit):
        whole("amount_column cannot be combined with debit_column/credit_column")
    if has_debit != has_credit:
        whole("debit_column and credit_column must be given together")
    if not has_amount and not has_debit:
        whole("need amount_column, or debit_column and credit_column")
    profile = ImportProfile(**values)
    if profile.thousands_separator and profile.thousands_separator == profile.decimal_separator:
        whole("decimal_separator and thousands_separator must differ")
    return profile


# ---- reading the file -----------------------------------------------------


def _records(text, delimiter):
    """Yield (starting_line, [cells]) for every CSV record in text; lines count from 1."""
    i = 0
    n = len(text)
    line = 1
    while i < n:
        start = line
        cells = []
        while True:
            buf = []
            if i < n and text[i] == '"':
                i += 1
                while i < n:
                    c = text[i]
                    if c == '"':
                        if i + 1 < n and text[i + 1] == '"':
                            buf.append('"')
                            i += 2
                            continue
                        i += 1
                        break
                    if c == "\n":
                        line += 1
                    buf.append(c)
                    i += 1
            while i < n and text[i] != delimiter and text[i] != "\n" and not (text[i] == "\r" and text[i + 1:i + 2] == "\n"):
                buf.append(text[i])
                i += 1
            cells.append("".join(buf))
            if i >= n:
                break
            if text[i] == delimiter:
                i += 1
                continue
            i += 2 if text[i] == "\r" else 1
            line += 1
            break
        yield start, cells


def _blank(cells):
    return all(c.strip() == "" for c in cells)


def _clean(cell):
    return " ".join(cell.split())


def _amount_regex(profile):
    dec = re.escape(profile.decimal_separator)
    digits = "[0-9]+"
    if profile.thousands_separator:
        digits = "[0-9]{1,3}(?:%s[0-9]{3})+|[0-9]+" % re.escape(profile.thousands_separator)
    return re.compile("([+-]?)(%s)(?:%s([0-9]+))?" % (digits, dec))


def _parse_amount_cell(cell, profile, regex, exponent):
    """Return signed minor units for a cell in the profile's number style."""
    text = cell.strip()
    negative_parens = False
    if len(text) >= 2 and text[0] == "(" and text[-1] == ")":
        negative_parens = True
        text = text[1:-1]
    m = regex.fullmatch(text)
    if m is None or (negative_parens and m.group(1)):
        raise _Bad("invalid amount %r" % cell.strip())
    sign, whole, frac = m.groups()
    whole = whole.replace(profile.thousands_separator, "") if profile.thousands_separator else whole
    frac = frac or ""
    if len(frac) > exponent:
        raise _Bad("invalid amount %r: %s has only %d decimals" % (cell.strip(), profile.currency, exponent))
    minor = int(whole + frac.ljust(exponent, "0"))
    return -minor if (sign == "-" or negative_parens) else minor


def _date_matcher(profile):
    return re.compile(_compile_format(profile.date_format))


def _read_date(cell, regex):
    text = cell.strip()
    m = regex.fullmatch(text)
    if m is None:
        raise _Bad("invalid date %r" % text)
    parts = m.groupdict()
    year = month = day = None
    for key, value in parts.items():
        slot, directive = key.split("_")
        if slot == "year":
            year = int(value) + (2000 if directive == "y" else 0)
        elif slot == "day":
            day = int(value)
        elif directive == "m":
            month = int(value)
        elif directive == "b":
            month = _MONTH_ABBR.index(value.lower()) + 1
        else:
            month = _MONTHS.index(value.lower()) + 1
    try:
        return date(year, month, day)
    except ValueError:
        raise _Bad("invalid date %r" % text) from None


def _resolve(column, header):
    if column is None:
        return None
    m = _COLUMN_NUMBER.fullmatch(column)
    if m is not None:
        return int(m.group(1)) - 1
    if header is None:
        raise CsvImportError("column %r needs a header row" % column)
    want = column.strip().lower()
    for index, cell in enumerate(header):
        if cell.strip().lower() == want:
            return index
    raise CsvImportError("column %r not found in the header" % column)


def _cell(cells, index, column):
    if index >= len(cells):
        raise _Bad("row too short: no column %s" % column)
    return cells[index]


def import_csv(text, profile, rules=None, existing=()):
    if isinstance(profile, str):
