    return tuple(sorted(set(t.lower() for t in names)))


_DIRECTIVES = {
    "Y": "[0-9]{4}",
    "y": "[0-9]{2}",
    "m": "[0-9]{1,2}",
    "d": "[0-9]{1,2}",
    "b": "(?i:%s)" % "|".join(_MONTH_ABBR),
    "B": "(?i:%s)" % "|".join(_MONTHS),
