        for name in _COLUMNS:
            if name in values and not values[name].startswith("#"):
                errors.append((where[name], "column name %r needs has_header = yes; use #N" % values[name]))
    if errors:
        number, message = min(errors, key=lambda e: e[0])
        raise CsvImportError("line %d: %s" % (number, message), line=number)

    def whole(message):
        raise CsvImportError(message, line=None)

    for name in ("date_column", "payee_column", "currency", "account"):
        if name not in values:
            whole("missing required setting %s" % name)
    has_amount = "amount_column" in values
    has_debit = "debit_column" in values
    has_credit = "credit_column" in values
    if has_amount and (has_debit or has_credit):
        whole("amount_column cannot be combined with debit_column/credit_column")
    if has_debit != has_credit:
        whole("debit_column and credit_column must be given together")
    if not has_amount and not has_debit:
        whole("need amount_column, or debit_column and credit_column")
    profile = ImportProfile(**values)
    if profile.thousands_separator and profile.thousands_separator == profile.decimal_separator:
        whole("decimal_separator and thousands_separator must differ")
    return profile


# ---- reading the file -----------------------------------------------------


def _records(text, delimiter):
    """Yield (starting_line, [cells]) for every CSV record in text; lines count from 1."""
    i = 0
    n = len(text)
    line = 1
    while i < n:
        start = line
        cells = []
        while True:
            buf = []
            if i < n and text[i] == '"':
                i += 1
                while i < n:
                    c = text[i]
                    if c == '"':
                        if i + 1 < n and text[i + 1] == '"':
                            buf.append('"')
                            i += 2
                            continue
                        i += 1
                        break
                    if c == "\n":
                        line += 1
                    buf.append(c)
                    i += 1
            while i < n and text[i] != delimiter and text[i] != "\n" and not (text[i] == "\r" and text[i + 1:i + 2] == "\n"):
                buf.append(text[i])
                i += 1
            cells.append("".join(buf))
            if i >= n:
                break
            if text[i] == delimiter:
                i += 1
                continue
            i += 2 if text[i] == "\r" else 1
            line += 1
            break
        yield start, cells


def _blank(cells):
    return all(c.strip() == "" for c in cells)


def _clean(cell):
    return " ".join(cell.split())


def _amount_regex(profile):
    dec = re.escape(profile.decimal_separator)
    digits = "[0-9]+"
    if profile.thousands_separator:
        digits = "[0-9]{1,3}(?:%s[0-9]{3})+|[0-9]+" % re.escape(profile.thousands_separator)
    return re.compile("([+-]?)(%s)(?:%s([0-9]+))?" % (digits, dec))


def _parse_amount_cell(cell, profile, regex, exponent):
    """Return signed minor units for a cell in the profile's number style."""
    text = cell.strip()
    negative_parens = False
    if len(text) >= 2 and text[0] == "(" and text[-1] == ")":
        negative_parens = True
        text = text[1:-1]
    m = regex.fullmatch(text)
    if m is None or (negative_parens and m.group(1)):
        raise _Bad("invalid amount %r" % cell.strip())
    sign, whole, frac = m.groups()
    whole = whole.replace(profile.thousands_separator, "") if profile.thousands_separator else whole
    frac = frac or ""
    if len(frac) > exponent:
        raise _Bad("invalid amount %r: %s has only %d decimals" % (cell.strip(), profile.currency, exponent))
    minor = int(whole + frac.ljust(exponent, "0"))
    return -minor if (sign == "-" or negative_parens) else minor


def _date_matcher(profile):
    return re.compile(_compile_format(profile.date_format))


def _read_date(cell, regex):
    text = cell.strip()
    m = regex.fullmatch(text)
    if m is None:
        raise _Bad("invalid date %r" % text)
    parts = m.groupdict()
    year = month = day = None
    for key, value in parts.items():
        slot, directive = key.split("_")
        if slot == "year":
            year = int(value) + (2000 if directive == "y" else 0)
        elif slot == "day":
            day = int(value)
        elif directive == "m":
            month = int(value)
        elif directive == "b":
            month = _MONTH_ABBR.index(value.lower()) + 1
        else:
            month = _MONTHS.index(value.lower()) + 1
    try:
        return date(year, month, day)
    except ValueError:
        raise _Bad("invalid date %r" % text) from None


def _resolve(column, header):
    if column is None:
        return None
    m = _COLUMN_NUMBER.fullmatch(column)
    if m is not None:
        return int(m.group(1)) - 1
    if header is None:
        raise CsvImportError("column %r needs a header row" % column)
    want = column.strip().lower()
    for index, cell in enumerate(header):
        if cell.strip().lower() == want:
            return index
    raise CsvImportError("column %r not found in the header" % column)


def _cell(cells, index, column):
    if index >= len(cells):
        raise _Bad("row too short: no column %s" % column)
    return cells[index]


def import_csv(text, profile, rules=None, existing=()):
    if isinstance(profile, str):
        profile = parse_profile(profile)
    elif not isinstance(profile, ImportProfile):
        raise CsvImportError("profile must be an ImportProfile or profile text")
    if isinstance(rules, str):
        rules = parse_rules(rules)
    elif rules is not None and not isinstance(rules, RuleSet):
        raise CsvImportError("rules must be a RuleSet, rules text or None")
    if not isinstance(text, str):
        raise CsvImportError("csv must be text")
    if text.startswith("\ufeff"):
        text = text[1:]
    pos = 0
    for _ in range(profile.skip_rows):
        m = _EOL.search(text, pos)
        if m is None:
            pos = len(text)
            break
        pos = m.end()
    body = text[pos:]
    base = text.count("\n", 0, pos) if False else None  # placeholder, replaced below
    skipped = len(_EOL.findall(text[:pos]))
    records = [(s + skipped, cells) for s, cells in _records(body, profile.delimiter) if not _blank(cells)]
    # Row numbers are file lines; the skipped lines were split at \n, \r\n or \r, so count those.
    header = None
    if profile.has_header:
        if not records:
            raise CsvImportError("the file has no header row")
        header = records.pop(0)[1]
    date_i = _resolve(profile.date_column, header)
    payee_i = _resolve(profile.payee_column, header)
    narr_i = _resolve(profile.narration_column, header)
    amount_i = _resolve(profile.amount_column, header)
    debit_i = _resolve(profile.debit_column, header)
    credit_i = _resolve(profile.credit_column, header)

    result = ImportResult()
    date_re = _date_matcher(profile)
    amount_re = _amount_regex(profile)
    exponent = _currency(profile.currency).exponent

    held = Counter()
    for tx in existing:
        for p in tx.postings:
            if p.account == profile.account and p.amount is not None:
                held[(tx.date, p.amount, tx.payee)] += 1
                break
    seen = Counter()

    for number, cells in records:
        try:
            on = _read_date(_cell(cells, date_i, profile.date_column), date_re)
            payee = _clean(_cell(cells, payee_i, profile.payee_column))
            if payee == "":
                raise _Bad("empty payee")
            narration = _clean(cells[narr_i]) if narr_i is not None and narr_i < len(cells) else ""
            if amount_i is not None:
                minor = _parse_amount_cell(_cell(cells, amount_i, profile.amount_column), profile, amount_re, exponent)
            else:
                debit = _cell(cells, debit_i, profile.debit_column)
                credit = _cell(cells, credit_i, profile.credit_column)
                if debit.strip() != "" and credit.strip() != "":
                    raise _Bad("both debit %r and credit %r are filled" % (debit.strip(), credit.strip()))
                if debit.strip() == "" and credit.strip() == "":
                    raise _Bad("neither debit nor credit is filled")
                if debit.strip() != "":
                    minor = -_parse_amount_cell(debit, profile, amount_re, exponent)
                else:
                    minor = _parse_amount_cell(credit, profile, amount_re, exponent)
            if profile.negate:
                minor = -minor
            if minor == 0:
                raise _Bad("amount is zero")
            flag = profile.flag
            tags = set(profile.tags)
            counter = profile.default_account
            if rules is not None:
                hit = rules.apply({"payee": payee, "narration": narration, "date": on,
                                   "amount": Money(minor, profile.currency)})
                if hit is not None:
                    counter = hit.get("account", counter)
                    payee = hit.get("payee", payee)
                    narration = hit.get("narration", narration)
                    flag = hit.get("flag", flag)
                    tags.update(hit.get("tags", ()))
            if counter is None:
                raise _Bad("no account for the other side: no rule matched and no default_account")
        except _Bad as e:
            result.errors.append((number, str(e)))
            continue
        tx = Transaction(on, payee, narration,
                         [Posting(profile.account, Money(minor, profile.currency)),
                          Posting(counter, Money(-minor, profile.currency))],
                         tuple(sorted(tags)), flag, None)
        key = (on, Money(minor, profile.currency), payee)
        seen[key] += 1
        if seen[key] <= held[key]:
            result.duplicates.append(tx)
        else:
            result.transactions.append(tx)
    return result

