def _records(text, delimiter):
    """Yield (starting_line, [cells]) for every CSV record in text; lines count from 1."""
    i = 0
    n = len(text)
    line = 1
    while i < n:
        start = line
        cells = []
        while True:
            buf = []
            if i < n and text[i] == '"':
                i += 1
                while i < n:
                    c = text[i]
                    if c == '"':
                        if i + 1 < n and text[i + 1] == '"':
                            buf.append('"')
                            i += 2
                            continue
                        i += 1
                        break
                    if c == "\n":
                        line += 1
                    buf.append(c)
                    i += 1
            while i < n and text[i] != delimiter and text[i] != "\n" and not (text[i] == "\r" and text[i + 1:i + 2] == "\n"):
                buf.append(text[i])
                i += 1
            cells.append("".join(buf))
            if i >= n:
                break
            if text[i] == delimiter:
