"""Importing a bank's CSV statements described by a profile."""
import re
from collections import Counter
from dataclasses import dataclass, field
from datetime import date
from typing import List, Optional, Tuple

from tallybook.currency import CURRENCIES, currency as _currency
from tallybook.errors import ParseError
from tallybook.model import Posting, Transaction
from tallybook.money import Money
from tallybook.rules import RuleSet, parse_rules, valid_rule_path

_TAG = re.compile(r"[A-Za-z0-9_-]+")
_COLUMN_NUMBER = re.compile(r"#([0-9]+)")
_EOL = re.compile(r"\r\n|\n|\r")

_MONTHS = ("january", "february", "march", "april", "may", "june", "july", "august", "september", "october",
           "november", "december")
_MONTH_ABBR = tuple(m[:3] for m in _MONTHS)

_DELIMITERS = {"comma": ",", "tab": "\t", "semicolon": ";", "pipe": "|", "space": " "}
_THOUSANDS = {"none": "", "comma": ",", "dot": ".", "space": " ", "apostrophe": "'"}


class CsvImportError(ParseError):
    def __init__(self, message="", line=None, **extra):
        super().__init__(message, line=line, **extra)


class _Bad(Exception):
    pass


@dataclass
class ImportProfile:
    date_column: str = ""
    payee_column: str = ""
    currency: str = ""
    account: str = ""
    narration_column: Optional[str] = None
    amount_column: Optional[str] = None
    debit_column: Optional[str] = None
    credit_column: Optional[str] = None
    default_account: Optional[str] = None
    date_format: str = "%Y-%m-%d"
    delimiter: str = ","
    skip_rows: int = 0
    has_header: bool = True
    negate: bool = False
    decimal_separator: str = "."
    thousands_separator: str = ""
    flag: str = "*"
    tags: Tuple[str, ...] = ()


@dataclass
class ImportResult:
    transactions: List[Transaction] = field(default_factory=list)
    duplicates: List[Transaction] = field(default_factory=list)
    errors: List[tuple] = field(default_factory=list)


# ---- profile --------------------------------------------------------------


def _bool(value):
    low = value.lower()
    if low in ("yes", "true"):
        return True
    if low in ("no", "false"):
        return False
    raise _Bad("expected yes/no or true/false, got %r" % value)


def _column(value):
    if value == "":
        raise _Bad("column must not be empty")
    if value.startswith("#"):
        m = _COLUMN_NUMBER.fullmatch(value)
        if m is None or int(m.group(1)) < 1:
            raise _Bad("bad column number %r" % value)
    return value


def _account(value):
    if not valid_rule_path(value):
        raise _Bad("invalid account path %r" % value)
    return value


def _currency_code(value):
    if value not in CURRENCIES:
        raise _Bad("unknown currency %r" % value)
    return value


def _delimiter(value):
    if value in _DELIMITERS:
        return _DELIMITERS[value]
    if len(value) == 1 and value not in '"\r\n':
        return value
    raise _Bad("bad delimiter %r" % value)


def _skip_rows(value):
    if re.fullmatch(r"[0-9]+", value) is None:
        raise _Bad("skip_rows must be a whole number, got %r" % value)
    return int(value)


def _decimal(value):
    if value not in (".", ","):
        raise _Bad("decimal_separator must be . or ,")
    return value


def _thousands(value):
    if value in _THOUSANDS:
        return _THOUSANDS[value]
    if value in (",", ".", "'", " "):
        return value
    raise _Bad("bad thousands_separator %r" % value)


def _flag(value):
    if value not in ("*", "!"):
        raise _Bad("flag must be * or !")
    return value


