    "date_column": ("date_column", _column),
    "payee_column": ("payee_column", _column),
    "narration_column": ("narration_column", _column),
    "amount_column": ("amount_column", _column),
    "debit_column": ("debit_column", _column),
    "credit_column": ("credit_column", _column),
    "currency": ("currency", _currency_code),
    "account": ("account", _account),
    "default_account": ("default_account", _account),
    "date_format": ("date_format", _date_format),
    "delimiter": ("delimiter", _delimiter),
    "skip_rows": ("skip_rows", _skip_rows),
    "has_header": ("has_header", _bool),
    "negate": ("negate", _bool),
    "decimal_separator": ("decimal_separator", _decimal),
    "thousands_separator": ("thousands_separator", _thousands),
    "flag": ("flag", _flag),
    "tags": ("tags", _tags),
