            if profile.negate:
                minor = -minor
            if minor == 0:
                raise _Bad("amount is zero")
            flag = profile.flag
            tags = set(profile.tags)
            counter = profile.default_account
            if rules is not None:
                hit = rules.apply({"payee": payee, "narration": narration, "date": on,
                                   "amount": Money(minor, profile.currency)})
                if hit is not None:
                    counter = hit.get("account", counter)
                    payee = hit.get("payee", payee)
                    narration = hit.get("narration", narration)
                    flag = hit.get("flag", flag)
                    tags.update(hit.get("tags", ()))
            if counter is None:
                raise _Bad("no account for the other side: no rule matched and no default_account")
        except _Bad as e:
            result.errors.append((number, str(e)))
            continue
        tx = Transaction(on, payee, narration,
                         [Posting(profile.account, Money(minor, profile.currency)),
                          Posting(counter, Money(-minor, profile.currency))],
                         tuple(sorted(tags)), flag, None)
        key = (on, Money(minor, profile.currency), payee)
        seen[key] += 1
        if seen[key] <= held[key]:
            result.duplicates.append(tx)
        else:
            result.transactions.append(tx)
    return result
